{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Client' AND span_name LIKE 'SELECT%' GROUP BY 1 ORDER BY 1",
          "claim": "In the incident, route-service's DB SELECT spans on ts.route, route_distances and route_stations jump to p50 about 4 ms and p95 400-500 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,3) p50_ms, round(quantile_cont(duration,0.95)/1e6,3) p95_ms FROM normal_traces WHERE service_name='ts-route-service' AND attr_span_kind='Client' AND span_name LIKE 'SELECT%' GROUP BY 1 ORDER BY 1",
          "claim": "In normal operation the same route-service DB SELECT spans run at p50 about 0.1-0.2 ms and p95 under 3 ms."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE service_name IN ('ts-route-service','mysql') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.cpu_limit_utilization','k8s.pod.memory_limit_utilization') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Route-service CPU and memory stay low (about 1% of limit) and mysql CPU is low, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.95)/1e6,1) callee_p95_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errors FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND s.service_name='ts-route-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel2-service calls to route-service slow to about 2.1 s p95 at the route-service callee; travel2 admin_trip spans reach 7.4 s."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.95)/1e6,1) callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND s.service_name='ts-route-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-service calls to route-service slow to about 1 s p95; travel admin_trip spans reach 5.9 s."
        }
      ]
    },
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(quantile_cont(s.duration,0.5)/1e6,1) callee_p50_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_errors FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE s.attr_span_kind='Server' AND s.service_name='ts-route-service' GROUP BY ALL ORDER BY n DESC",
          "claim": "UI dashboard's GET /routes calls to route-service take about 36 s p50, with 10 of 11 erroring."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%routeservice%' GROUP BY 1,2",
          "claim": "User-facing dashboard GET /api/v1/routeservice/routes requests take about 20 s p50 during the incident."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-admin-travel-service','ts-travel-service') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Admin-travel and travel admin_trip server spans run at 5.9-11.9 s during the incident."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%admintravel%' GROUP BY 1,2",
          "claim": "UI dashboard's admintravel request takes about 9.9 s, with the slowdown inherited from the admin-travel chain."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel2-service','ts-ui-dashboard') AND attr_span_kind='Server' AND (span_name LIKE '%travel2%' OR span_name LIKE '%travel%') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Travel2-service admin_trip server spans reach about 7.4 s, consistent with its slowed route-service calls feeding the dashboard."
        }
      ]
    }
  ]
}
